const { app, BrowserWindow } = require("electron");
const fs = require("fs");
const OUT = "C:/Users/chris/AppData/Local/Temp/agents/chat-images/onboarding-kept/";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
app.whenReady().then(async () => {
  const w = new BrowserWindow({ width: 1280, height: 800, show: true, useContentSize: true, webPreferences:{backgroundThrottling:false} });
  await w.loadURL("http://localhost:5173/");
  const js = (c) => w.webContents.executeJavaScript(c);
  const click = (sel, text) => js(`(()=>{const e=[...document.querySelectorAll(${JSON.stringify(sel)})].find(e=>!${JSON.stringify(text)}||e.textContent.trim().startsWith(${JSON.stringify(text)}));if(e)e.click();return !!e})()`);
  const R = `(()=>{const r=e=>{const b=e.getBoundingClientRect();return [b.left,b.top,b.right,b.bottom].map(Math.round)};
   const cards=[...document.querySelectorAll('.kept-card')];
   const of=[];cards.forEach((c,i)=>{[c,...c.querySelectorAll('*')].forEach(e=>{if(e.scrollHeight>e.clientHeight+1&&e.clientHeight>0||e.scrollWidth>e.clientWidth+1&&e.clientWidth>0)of.push(i+' '+e.tagName+'.'+e.className+' sh'+e.scrollHeight+'/ch'+e.clientHeight+' sw'+e.scrollWidth+'/cw'+e.clientWidth)})});
   // visible text ranges
   const tx=[...document.querySelectorAll('.first-run-headline,.first-run-body,.first-run-actions button')].map(e=>{const g=document.createRange();g.selectNodeContents(e);return [e.textContent.trim().slice(0,16),[...g.getClientRects()].map(x=>[x.left,x.top,x.right,x.bottom])]});
   const ov=[];cards.forEach((c,i)=>{const p=r(c);tx.forEach(([t,rs])=>rs.forEach(a=>{if(p[0]<a[2]&&p[2]>a[0]&&p[1]<a[3]&&p[3]>a[1])ov.push(i+' x '+t)}))});
   return JSON.stringify({n:cards.length,of,ov})})()`;
  await sleep(2000);
  await click('[aria-label="Settings"]'); await sleep(500);
  await click(".settings-tab","General"); await sleep(300);
  await click(".settings-data-button","Show the welcome"); await sleep(2500);
  await click(".first-run-primary","Continue");
  const t0=Date.now();
  for (const s of [2,30]) {
    const d=s*1000-(Date.now()-t0); if(d>0) await sleep(d);
    fs.writeFileSync(OUT+`v5-${s}s.png`,(await w.webContents.capturePage()).toPNG());
    console.log(s,await js(R));
  }
  app.quit();
});
